using Clock=std::chrono::steady_clock;
double millis(Clock::time_point a,Clock::time_point b){return std::chrono::duration<double,std::milli>(b-a).count();}
void save(const std::string& name,const void* data,size_t bytes){std::ofstream f(name,std::ios::binary);f.write(static_cast<const char*>(data),bytes);if(!f)throw std::runtime_error("write failed: "+name);}
std::vector<char> load(const std::string& name,size_t bytes){std::ifstream f(name,std::ios::binary|std::ios::ate);if(!f||size_t(f.tellg())!=bytes)throw std::runtime_error("file length: "+name);f.seekg(0);std::vector<char> v(bytes);f.read(v.data(),bytes);if(!f)throw std::runtime_error("file read: "+name);return v;}
template<class T>std::vector<char> dump(T& t){if(!t.waitForReady(std::chrono::milliseconds(10000)))throw std::runtime_error("tensor timeout");std::ostringstream s;t.dump(s,"SFB");auto b=s.str();return {b.begin(),b.end()};}
